// spec: .qa/e2e/specs/auth-phone-otp.md
// seed: tests/seed.spec.ts
import { test, expect } from '@playwright/test';

test.describe('Вход/регистрация — телефон и OTP', () => {
  test('«+972» слева от поля номера на 360/375/390 — регистрация через /terms @iphone @prod-safe (#4aa498)', async ({ page }) => {
    // 1. Перехватить otp/verify.
    await page.route('**/auth/v1/otp*', (r) => r.fulfill({ status: 200, contentType: 'application/json', body: '{}' }));
    await page.route('**/auth/v1/verify*', (r) =>
      r.fulfill({ status: 400, contentType: 'application/json', body: JSON.stringify({ code: 400, error_code: 'otp_expired', msg: 'Token has expired or is invalid' }) }),
    );

    // 2. /welcome → «בוא/י נתחיל» → дождаться /terms.
    await page.goto('/welcome');
    await page.getByRole('button', { name: 'בוא/י נתחיל' }).click();
    await page.waitForURL(/\/terms/);

    // 3. Отметить обе галочки, нажать продолжить → дождаться /phone.
    await page.getByRole('checkbox', { name: 'קראתי ואני מסכים/ה לתנאי השימוש ולמדיניות הפרטיות' }).click();
    await page.getByRole('checkbox', { name: 'אני מעל גיל 18' }).click();
    await page.getByRole('button', { name: 'מסכים/ה, ממשיכים' }).click();
    await page.waitForURL(/\/phone/);
    await expect(page.getByText('מה מספר הטלפון שלך?')).toBeVisible();
    const input = page.getByRole('textbox', { name: '50-000-0000' });

    // 4. Для 360/375/390 замерить «+972» и поле номера.
    for (const width of [360, 375, 390]) {
      await page.setViewportSize({ width, height: 812 });
      const prefix = page.getByText('+972', { exact: true });
      await expect(prefix).toBeVisible();
      const p = await prefix.boundingBox();
      const i = await input.boundingBox();
      expect(p, `prefix box @${width}`).not.toBeNull();
      expect(i, `input box @${width}`).not.toBeNull();
      expect(p!.x + p!.width, `«+972» слева от поля @${width}`).toBeLessThanOrEqual(i!.x);
    }
  });
});
